private boolean validateProcurementCategoryIsConsistentWithItemNumber()
{
    if ((this.isFieldSet(fieldNum(METSATVendorInvoiceLineEntity, ItemNumber))
            || this.isFieldSet(fieldNum(METSATVendorInvoiceLineEntity, ProcurementCategoryName)))
        && this.ItemNumber
        && this.ProcurementCategoryName
        && this.findProcurementCategoryForItem(this.ItemNumber).Name != this.ProcurementCategoryName)
    {
        return checkFailed("@SCM:PurchPurchaseOrderLineEntityInconsistentProcurementCategory");
    }

    return true;
}

    private boolean validatePurchaseOrderPurchLineNumberCombination()
    {
        boolean isPurchaseOrderSet = this.isFieldSet(fieldNum(METSATVendorInvoiceLineEntity, PurchaseOrder)) && this.PurchaseOrder != '';
        boolean isPurchLineNumberSet = this.isFieldSet(fieldNum(METSATVendorInvoiceLineEntity, PurchLineNumber)) && this.PurchLineNumber != 0;

        if ((isPurchaseOrderSet || isPurchLineNumberSet) && !(isPurchaseOrderSet && isPurchLineNumberSet))
        {
            return checkFailed(strFmt("@AccountsPayable:PurchOrderPurchLineNumberCombination", 
				fieldId2Name(tableNum(METSATVendorInvoiceLineEntity), fieldNum(METSATVendorInvoiceLineEntity, PurchaseOrder)),
                fieldId2Name(tableNum(METSATVendorInvoiceLineEntity), fieldNum(METSATVendorInvoiceLineEntity, PurchLineNumber))));
        }

        return true;
    }

private EcoResCategory findProcurementCategoryForItem(ItemId _itemId)
{
    EcoResProductCategory productCategory = EcoResProductCategory::findByItemIdCategoryHierarchyRole(_itemId, EcoResCategoryNamedHierarchyRole::Procurement);
    return EcoResCategory::find(productCategory.Category);
}

public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    switch (_dataSourceCtx.name())
    {
        case dataEntityDataSourceStr(METSATVendorInvoiceLineEntity, InventDim):
            return true;

        case dataEntityDataSourceStr(METSATVendorInvoiceLineEntity, BudgetReservationHeader_PSN),
            dataEntityDataSourceStr(METSATVendorInvoiceLineEntity, BudgetReservationLine_PSN):
            _dataSourceCtx.setDatabaseOperation(DataEntityDatabaseOperation::None);
            break;
    }

    return super(_entityCtx, _dataSourceCtx);
}

private void defaultVendorInvoicePurchLine(VendInvoiceInfoLine _invoiceLine)
{
    if (this.PurchaseOrder != '' && this.PurchLineNumber != 0)
    {
        PurchLine purchLine = purchLine::find(this.PurchaseOrder, this.PurchLineNumber);
        _invoiceLine.PurchLineRecId = purchLine.RecId;
        _invoiceLine.InventTransId = purchLine.InventTransId;
        _invoiceLine.InventDimId = purchLine.InventDimId;
        _invoiceLine.PurchUnit = purchLine.PurchUnit;
    }
    else
    {
        // Resolve InventDim values to InventDimID if any values are set
        if (this.InventInventoryDimensionEntityFieldsMapping::isAnyInventDimFieldSet())
        {
            _invoiceLine.InventDimId = this.InventInventoryDimensionEntityFieldsMapping::resolveInventDimId();
        }
    }
}

/// <summary>
///
/// </summary>
public static str ItemName()
{
    return SysComputedColumn::if(
        SysComputedColumn::notEqualExpression(SysComputedColumn::comparisonField(tableStr(METSATVendorInvoiceLineV2Entity), dataEntityDataSourceStr(METSATVendorInvoiceLineV2Entity, EcoResProductTranslation), fieldStr(EcoResProductTranslation, Name)),
                                          SysComputedColumn::comparisonLiteral('')),
        SysComputedColumn::returnField(tableStr(SalesInvoiceLineEntity), dataEntityDataSourceStr(METSATVendorInvoiceLineV2Entity, EcoResProductTranslation), fieldStr(EcoResProductTranslation, Name)),
        SysComputedColumn::returnField(tableStr(SalesInvoiceLineEntity), dataEntityDataSourceStr(METSATVendorInvoiceLineV2Entity, EcoResProductTranslationMaster), fieldStr(EcoResProductTranslation, Name)));
}
